package com.obysoft.faithOS.controller;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.AbsenceService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/absences")public class AbsenceController{private final AbsenceService service;public AbsenceController(AbsenceService s){service=s;}@PostMapping public ResponseEntity<AbsenceResponse> submit(@Valid @RequestBody AbsenceRequest r){return ResponseEntity.status(201).body(service.submit(r));}@GetMapping("/mine")public List<AbsenceResponse> mine(){return service.mine();}@GetMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR','LEADER')")public List<AbsenceResponse> all(){return service.church();}@PatchMapping("/{id}/acknowledge")@PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR','LEADER')")public AbsenceResponse acknowledge(@PathVariable Long id){return service.acknowledge(id);}}
